from pathlib import Path
import re
root=Path('src')
headers={str(p.relative_to(root)):p for p in Path('src/climate').rglob('*.h')}
g={k:set() for k in headers}
rx=re.compile(r'^#include \"([^\"]+)\"')
for k,p in headers.items():
    for line in p.read_text(errors='ignore').splitlines():
        m=rx.match(line)
        if m and m.group(1) in headers: g[k].add(m.group(1))
state={}; stack=[]; cycles=[]
def dfs(n):
    state[n]=1; stack.append(n)
    for v in g[n]:
        if state.get(v,0)==0: dfs(v)
        elif state.get(v)==1:
            i=stack.index(v); cycles.append(stack[i:]+[v])
    stack.pop(); state[n]=2
for n in g:
    if state.get(n,0)==0: dfs(n)
print('=== INCLUDE GRAPH ===')
print('headers',len(headers),'edges',sum(map(len,g.values())),'cycles',len(cycles))
for c in cycles[:20]: print(' -> '.join(c))
